#!/usr/bin/env python3
"""Transient read-only audit of the hub result-acceptance store.
Opens /data/k3/p5_queue/jobs.sqlite with mode=ro via WSL-side SSH execution
on the hub; never writes. Emits mechanical exactly-once counters.
"""
import json
import sqlite3

DB = "/data/k3/p5_queue/jobs.sqlite"


def main() -> int:
    con = sqlite3.connect(f"file:{DB}?mode=ro", uri=True, timeout=5)
    con.row_factory = sqlite3.Row

    def one(query, *args):
        return con.execute(query, *args).fetchone()[0]

    tables = [row[0] for row in con.execute(
        "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
    )]
    counts = {t: one(f'SELECT count(*) FROM "{t}"') for t in tables}
    dup_canonical_per_job = one(
        "SELECT count(*) FROM (SELECT job_id,count(*) c FROM results GROUP BY job_id HAVING c>1)"
    )
    dup_canonical_per_attempt = one(
        "SELECT count(*) FROM (SELECT attempt_id,count(*) c FROM results GROUP BY attempt_id HAVING c>1)"
    )
    conflicting_orphan_replays = one(
        "SELECT count(*) FROM (SELECT attempt_id,count(distinct manifest_sha) d "
        "FROM orphan_results GROUP BY attempt_id HAVING d>1)"
    )
    dup_logical_trials_jobs = one(
        "SELECT count(*) FROM (SELECT logical_trial_id,count(*) c FROM jobs GROUP BY logical_trial_id HAVING c>1)"
    )
    dup_trial_registrations = one(
        "SELECT count(*) FROM (SELECT logical_trial_id,count(*) c FROM trial_registrations "
        "GROUP BY logical_trial_id HAVING c>1)"
    )
    lost_accepted = one(
        "SELECT count(*) FROM results WHERE NOT EXISTS "
        "(SELECT 1 FROM jobs WHERE jobs.canonical_result_id=results.result_id)"
    )
    out = {
        "opened": "file-uri mode=ro",
        "database": DB,
        "journal_mode": one("PRAGMA journal_mode"),
        "integrity_check": one("PRAGMA integrity_check"),
        "table_counts": counts,
        "jobs_by_state": {
            row[0]: row[1] for row in con.execute("SELECT state,count(*) FROM jobs GROUP BY state")
        },
        "event_types": {
            row[0]: row[1] for row in con.execute(
                "SELECT event_type,count(*) FROM event_outbox GROUP BY event_type"
            )
        },
        "metrics": {
            "canonical_results": counts.get("results", 0),
            "duplicate_accepted_results": dup_canonical_per_job + dup_canonical_per_attempt,
            "duplicate_logical_trials": dup_logical_trials_jobs + dup_trial_registrations,
            "lost_committed_checkpoint": None,
            "lost_accepted_results": lost_accepted,
            "conflicting_orphan_manifest_replays": conflicting_orphan_replays,
        },
    }
    con.close()
    print(json.dumps(out, indent=2, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

